<template><view class="page"><text class="title">{{career.careerName}}</text><text class="intro">{{career.oneLineIntro}}</text><view class="info-card"><text class="section">这个职业主要做什么？</text><text class="body">{{career.mainWork || '暂无介绍'}}</text></view><view class="info-card"><text class="section">一天可能做什么？</text><text class="body">{{career.dayExample || '暂无介绍'}}</text></view><view class="info-card"><text class="section">为什么会有这样的职业？</text><text class="body">{{career.whyExists || '暂无介绍'}}</text></view><view class="actions"><button hover-class="button-hover" :disabled="readOnly" @click="add">加入探索清单</button><button type="primary" hover-class="button-hover" :disabled="readOnly" @click="finish">完成探索</button></view><view class="nav-actions"><button hover-class="button-hover" @click="moreInCategory">换一个职业继续了解</button><button hover-class="button-hover" @click="moreCategories">换一个职业大类继续了解</button></view></view></template>
<script>
import { getRecord, browseCareer, addExplorationItem, userMessage } from '@/api/zycck'
export default { data: () => ({ recordId: '', instanceId: '', gameId: '', categoryId: '', careerId: '', career: {}, readOnly: false }), onLoad(o) { Object.assign(this, { recordId: o.recordId || '', instanceId: o.instanceId || '', gameId: o.gameId || '', categoryId: o.categoryId || '', careerId: o.careerId || '', readOnly: o.readOnly === '1' }); this.load() }, methods: { async load() { try { const r = await getRecord(this.recordId, { careerId: this.careerId }); const d = r.data || {}; this.career = d.career || d.currentCareer || { careerId: this.careerId, careerName: '职业详情' }; this.readOnly = this.readOnly || d.status === 'finished' || (d.record && d.record.status === 'finished'); if (!this.readOnly) await browseCareer(this.recordId, this.careerId) } catch (e) { uni.showToast({ title: userMessage(e, '职业详情加载失败，请重试'), icon: 'none' }) } }, async add() { if (this.readOnly) return; try { await addExplorationItem(this.recordId, this.careerId); uni.showToast({ title: '已加入探索清单', icon: 'success' }) } catch (e) { uni.showToast({ title: userMessage(e, '加入清单失败，请重试'), icon: 'none' }) } }, async finish() { if (this.readOnly) return; uni.redirectTo({ url: `/pages/zycck/exploration-list?recordId=${this.recordId}&instanceId=${this.instanceId}&gameId=${this.gameId}&readOnly=0` }) }, moreInCategory() { uni.redirectTo({ url: `/pages/zycck/careers?recordId=${this.recordId}&instanceId=${this.instanceId}&gameId=${this.gameId}&categoryId=${this.categoryId}&readOnly=${this.readOnly ? '1' : '0'}` }) }, moreCategories() { uni.redirectTo({ url: `/pages/zycck/categories?recordId=${this.recordId}&instanceId=${this.instanceId}&gameId=${this.gameId}&readOnly=${this.readOnly ? '1' : '0'}` }) } } }
</script>
<style scoped>.page{min-height:100vh;padding:48rpx 40rpx;box-sizing:border-box;background:#f5f7fb;display:flex;flex-direction:column;justify-content:center;animation:pageIn .35s ease-out}.title{display:block;font-size:52rpx;font-weight:800;color:#1a2c4a}.intro{display:block;margin:20rpx 0 28rpx;color:#64748b;font-size:28rpx}.info-card{background:#fff;padding:28rpx;border-radius:18rpx;margin-bottom:18rpx;box-shadow:0 6rpx 18rpx rgba(31,41,55,.04)}.section{display:block;font-weight:700;font-size:31rpx;margin-bottom:14rpx;color:#20252b}.body{display:block;font-size:28rpx;line-height:1.8;color:#4b5563}.actions,.nav-actions{display:flex;gap:20rpx;margin-top:24rpx}.actions button,.nav-actions button{flex:1}.nav-actions{flex-direction:column}.button-hover{opacity:.8;transform:scale(.98)}@keyframes pageIn{from{opacity:0;transform:translateY(18rpx)}to{opacity:1;transform:translateY(0)}}.button-hover{transform:none!important}.card-hover{transform:none!important}.awareness-hover{transform:none!important}</style>
